  const required = entries.filter((entry) => entry.required);
  const requiredBytes = required.reduce((total, entry) => total + entry.cost, 0);
  if (requiredBytes > maxBytes) {
    invalid('required sections exceed maxBytes');
  }

  const optional = entries
    .filter((entry) => !entry.required)
